mapper.insert:
INSERT INTO knowledge_message (
  chat_id, role, content, sources, created_at
) VALUES (
  #{chatId}, #{role}, #{content}, CAST(#{sourcesJson} AS JSONB), #{createdAt}
)

mapper.select:
SELECT 
FROM knowledge_message message
INNER JOIN knowledge_chat chat ON chat.chat_id = message.chat_id
WHERE message.chat_id = #{chatId}
  AND chat.user_id = #{userId}
  AND chat.deleted_at IS NULL

  AND message.message_id < #{beforeMessageId}

ORDER BY message.message_id DESC
LIMIT #{limit}
